const searches = [
  {
    name: "ai-automation",
    enabled: true,
    text: "AI automation engineer",
    area: "1",
    pages: 1,
  },
];

const output = [];

for (const search of searches) {
  if (!search.enabled) continue;

  const pages = Math.max(1, Number(search.pages || 1));

  for (let page = 0; page < pages; page += 1) {
    const queryParams = {
      text: search.text,
      area: String(search.area),
      order_by: "publication_time",
      page: String(page),
    };

    const queryString = Object.entries(queryParams)
      .map(([key, value]) =>
        `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`
      )
      .join("&");

    output.push({
      json: {
        source_query: search.name,
        search_text: search.text,
        page,
        url: `https://hh.ru/search/vacancy?${queryString}`,
      },
    });
  }
}

if (output.length === 0) {
  throw new Error("No enabled search configurations");
}

return output;

const response = $input.first().json;
const htmlCandidates = [
  typeof response === "string" ? response : null,
  response.data,
  response.body,
  response.response,
];
const html = htmlCandidates.find((value) => typeof value === "string");

if (!html) {
  throw new Error("HTTP Request did not return an HTML string");
}

const source = $("Generate Search URLs").first().json;
const normalizedHtml = html.replace(/&amp;/g, "&");
const pattern = /href="([^"]*\/vacancy\/(\d+)[^"]*)"/g;
const vacancies = new Map();

for (const match of normalizedHtml.matchAll(pattern)) {
  const vacancyId = match[2];
  const canonicalUrl = `https://hh.ru/vacancy/${vacancyId}`;

  if (!vacancies.has(vacancyId)) {
    vacancies.set(vacancyId, {
      vacancy_id: vacancyId,
      url: canonicalUrl,
      source_query: source.source_query,
      search_text: source.search_text,
      search_page: source.page,
    });
  }
}

if (vacancies.size === 0) {
  throw new Error("No vacancy links found in the search HTML");
}

return Array.from(vacancies.values(), (vacancy) => ({ json: vacancy }));

const items = $input.all();

if (items.length === 0) {
  throw new Error("No vacancies available for the detail smoke test");
}

return [items[0]];

const response = $input.first().json;
const htmlCandidates = [
  typeof response === "string" ? response : null,
  response.data,
  response.body,
  response.response,
];
const html = htmlCandidates.find((value) => typeof value === "string");

if (!html) {
  throw new Error("Vacancy request did not return an HTML string");
}

const source = $("Select First Vacancy").item.json;

function decodeEntities(value) {
  return String(value || "")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, String.fromCharCode(34))
    .replace(/&#39;/g, String.fromCharCode(39))
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">");
}

function cleanHtml(value) {
  return decodeEntities(
    String(value || "")
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<\/p>/gi, "\n")
      .replace(/<\/li>/gi, "\n")
      .replace(/<[^>]+>/g, " ")
  )
    .replace(/[ \t]+/g, " ")
    .replace(/ *\n */g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function firstMatch(pattern) {
  const match = html.match(pattern);
  return match ? cleanHtml(match[1]) : "";
}

const title = firstMatch(/<title[^>]*>([\s\S]*?)<\/title>/i);
const seoDescription = firstMatch(/<meta[^>]+name="description"[^>]+content="([^"]*)"/i);
const company = firstMatch(/<[^>]+data-qa="vacancy-company-name"[^>]*>([\s\S]*?)<\/[^>]+>/i);

const descriptionText = firstMatch(
  /<div[^>]*data-qa="vacancy-description"[^>]*>([\s\S]*?)<\/div>/i
).slice(0, 20000);

if (!title) {
  throw new Error("Vacancy title was not extracted");
}

return [{
  json: {
    vacancy_id: source.vacancy_id,
    url: source.url,
    source_query: source.source_query,
    title,
    company,
    seo_description: seoDescription,
    description_text: descriptionText,
    description_found: descriptionText.length > 100,
    description_length: descriptionText.length,
    fetched_at: new Date().toISOString(),
  },
}];
